using Microsoft.CodeAnalysis;

namespace Phoney.SourceGenerator.Tests;

/// <summary>
/// Every scalar type the reflection model generates is generated by the source generator too (the runtime tests list the same types), so a category added to
/// one side fails a test instead of silently leaving members of that type at their default in generated models.
/// </summary>
public sealed class ScalarCoverageTests
{
    private static readonly (string Type, string Helper)[] Scalars =
    [
        ("string", "String"), ("char", "Char"), ("bool", "Bool"), ("byte", "Number<byte>"), ("sbyte", "Number<sbyte>"), ("short", "Number<short>"),
        ("ushort", "Number<ushort>"), ("int", "Number<int>"), ("uint", "Number<uint>"), ("long", "Number<long>"), ("ulong", "Number<ulong>"),
        ("float", "Number<float>"), ("double", "Number<double>"), ("decimal", "Number<decimal>"), ("System.Guid", "Guid"), ("System.DateTime", "DateTime"),
        ("System.DateTimeOffset", "DateTimeOffset"), ("System.DateOnly", "DateOnly"), ("System.TimeOnly", "TimeOnly"), ("System.TimeSpan", "TimeSpan"),
        ("System.Uri", "Uri"), ("System.Half", "Number<global::System.Half>"), ("System.Int128", "Number<global::System.Int128>"),
        ("System.UInt128", "Number<global::System.UInt128>"), ("System.Numerics.BigInteger", "Number<global::System.Numerics.BigInteger>"),
        ("nint", "Number<nint>"), ("nuint", "Number<nuint>"), ("System.Text.Rune", "Rune"), ("System.Net.IPAddress", "IPAddress"),
        ("System.Version", "Version"), ("System.DayOfWeek", "Enum<global::System.DayOfWeek>"),
    ];

    [Test]
    public void Every_scalar_type_is_produced_by_a_convention_value_call(CancellationToken cancellationToken)
    {
        var properties = string.Join("\n", Scalars.Select((s, i) => $"    public {s.Type} P{i} {{ get; set; }}"));
        var (driver, output, diagnostics) = GeneratorHarness.Run($$"""
            using Phoney.Generation;
            public class Everything
            {
            {{properties}}
            }
            [FakeFor<Everything>] public static partial class EverythingFakes;
            """);
        diagnostics.ShouldBeEmpty();
        output.GetDiagnostics(cancellationToken).Where(d => d.Severity == DiagnosticSeverity.Error).ShouldBeEmpty();
        var source = string.Concat(driver.GetRunResult().GeneratedTrees.Select(t => t.ToString()));

        foreach (var (type, helper) in Scalars)
            source.ShouldContain("ConventionValues." + helper + "(", customMessage: type);
    }
}
